INSERT INTO `announcements` VALUES (9,'国家药监局关于40批次不符合规定化妆品的通告','在2025年国家化妆品抽样检验工作中，经浙江省食品药品检验研究院等单位检验，产品标签标示名称为Orginese祛痘净肤水光面膜等40批次化妆品不符合规定（见附件）。\r\n\r\n　　根据《化妆品监督管理条例》《化妆品生产经营监督管理办法》《化妆品抽样检验管理办法》，国家药品监督管理局已要求上海、江苏、安徽、广东等省（市）药品监督管理部门，对上述不符合规定化妆品涉及的注册人、备案人、受托生产企业等依法立案调查，责令相关企业依法采取风险控制措施并开展自查整改。各省级药品监督管理部门要依法责令相关化妆品经营者停止经营上述化妆品，并依法调查其进货查验记录等情况，对违法产品进行追根溯源，发现违法行为的，依法严肃查处；涉嫌犯罪的，依法移送公安机关。\r\n\r\n　　特此通告。','2026年第9号','2026-04-01',NULL,NULL,'浙江省食品药品检验研究院',40,'/uploads/announcements/1775723453863-284442745.doc','1775117399177089339.doc','published',NULL,2,'2026-04-09 08:30:53','2026-04-11 04:15:52'),(10,'国家药监局关于22批次化妆品检出禁用原料的通告','在2025年国家化妆品抽样检验工作中，经内蒙古自治区药品检验研究院等单位检验，产品标签标示名称为德皙妮草本祛痘精华水等22批次化妆品不符合规定，检出《化妆品安全技术规范（2015年版）》中规定的禁用原料（见附件）。\r\n\r\n　　根据《化妆品监督管理条例》《化妆品生产经营监督管理办法》《化妆品抽样检验管理办法》，国家药监局已要求浙江、广东省药品监督管理部门对上述不符合规定化妆品涉及的注册人、备案人、受托生产企业等依法立案调查，责令相关企业依法采取风险控制措施并开展自查整改。各省级药品监督管理部门要依法责令相关化妆品经营者停止经营上述化妆品，并依法调查其进货查验记录等情况，对违法产品进行追根溯源，发现违法行为的，依法严肃查处；涉嫌犯罪的，依法移送公安机关。\r\n\r\n　　特此通告。','2026年第10号','2026-04-09',NULL,NULL,'内蒙古自治区药品检验研究院',22,'/uploads/announcements/1775879819167-670765912.doc','1775811531359011185.doc','published',NULL,1,'2026-04-11 03:56:59','2026-04-11 04:07:53'),(11,'国家药监局关于50批次不符合规定化妆品的通告','在2025年国家化妆品抽样检验工作中，经贵州省食品药品检验所等单位检验，产品标签标示名称为俏因子草本清肌泥膜粉等50批次化妆品不符合规定（见附件）。\r\n\r\n　　根据《化妆品监督管理条例》《化妆品生产经营监督管理办法》《化妆品抽样检验管理办法》，国家药品监督管理局已要求浙江、广东、青海省药品监督管理部门对上述不符合规定化妆品涉及的注册人、备案人、受托生产企业等依法立案调查，责令相关企业依法采取风险控制措施并开展自查整改。各省级药品监督管理部门要依法责令相关化妆品经营者停止经营上述化妆品，并依法调查其进货查验记录等情况，对违法产品进行追根溯源，发现违法行为的，依法严肃查处；涉嫌犯罪的，依法移送公安机关。\r\n\r\n　　特此通告','（2026年第6号）','2026-02-03',NULL,NULL,'贵州省食品药品检验所',50,'/uploads/announcements/1775879887432-972934139.doc','1770257663663076547.doc','published',NULL,1,'2026-04-11 03:58:07','2026-04-11 03:58:15'),(12,'国家药监局关于18批次化妆品检出禁用原料的通告（2025年第46号）','在2025年国家化妆品抽样检验工作中，经安徽省食品药品检验研究院等单位检验，产品标签标示名称为薇秘水漾修颜粉底液 01等18批次化妆品不符合规定，检出《化妆品安全技术规范（2015年版）》中规定的禁用原料（见附件）。\r\n\r\n　　根据《化妆品监督管理条例》《化妆品生产经营监督管理办法》《化妆品抽样检验管理办法》，国家药品监督管理局已要求辽宁、上海、浙江、山东、湖北、广东等省（市）药品监督管理部门对上述不符合规定化妆品涉及的注册人、备案人、受托生产企业等依法立案调查，责令相关企业依法采取风险控制措施并开展自查整改。各省（区、市）药品监督管理部门要依法责令相关化妆品经营者停止经营上述化妆品，并依法调查其进货查验记录等情况，对违法产品进行追根溯源；发现违法行为的，依法严肃查处；涉嫌犯罪的，依法移送公安机关。\r\n\r\n　　特此通告。','（2025年第46号）','2025-12-19',NULL,NULL,'安徽省食品药品检验研究院',18,'/uploads/announcements/1775880526224-655149574.doc','1766395027103012146.doc','published',NULL,1,'2026-04-11 04:08:46','2026-04-11 04:12:15');
/*!40000 ALTER TABLE `announcements` ENABLE KEYS */;
