DROP TABLE IF EXISTS `flight_inspection_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `flight_inspection_detail` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `company_name` varchar(100) NOT NULL COMMENT '企业名称',
  `license_code` varchar(50) DEFAULT NULL COMMENT '化妆品生产许可证编号',
  `credit_code` varchar(50) DEFAULT NULL COMMENT '社会信用代码',
  `company_address` varchar(255) DEFAULT NULL COMMENT '企业地址',
  `inspect_org` varchar(100) DEFAULT NULL COMMENT '检查单位',
  `inspect_basis` text COMMENT '检查依据',
  `defect_problem` text COMMENT '检查发现缺陷和问题',
  `measure` text COMMENT '处理措施',
  `publish_date` date DEFAULT NULL COMMENT '发布日期',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '记录更新时间',
  `supervision_id` int DEFAULT NULL,
  `sequence_no` int NOT NULL DEFAULT '1',
  `title` varchar(255) DEFAULT NULL,
  `production_license_no` varchar(255) DEFAULT NULL,
  `social_credit_code` varchar(255) DEFAULT NULL,
  `inspection_unit` varchar(255) DEFAULT NULL,
  `inspection_basis` longtext,
  `defects_and_problems` longtext,
  `handling_measures` longtext,
  `publish_date_text` varchar(100) DEFAULT NULL,
  `raw_text` longtext,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `attachment_name` varchar(255) DEFAULT NULL,
  `attachment_path` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_flight_inspection_detail_supervision` (`supervision_id`),
  KEY `idx_flight_inspection_detail_company_name` (`company_name`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='化妆品企业飞行检查调查详情表';
/*!40101 SET character_set_client = @saved_cs_client */;

