INSERT INTO `flight_inspection_detail` VALUES (17,'安徽特仑沙克生物科技研究有限公司',NULL,NULL,'合肥市新站区新蚌埠路3768号佳海工业城G90',NULL,NULL,NULL,NULL,'2026-01-08','2026-04-09 16:33:47','2026-04-09 16:33:47',22,1,'安徽特仑沙克生物科技研究有限公司飞行检查结果','皖妆20220006','91340102MA2RRWYE0Y','国家药监局食品药品审核查验中心','《化妆品监督管理条例》《化妆品生产质量管理规范》\n《化妆品生产质量管理规范检查要点及判定原则》等','该企业在质量保证与控制方面存在未有效执行留样管理制度、未按规定保存留样记录等问题；在厂房设施与设备管理方面存在擅自改变生产车间的功能区域划分等问题；在物料与产品管理方面存在未有效执行物料进货查验记录制度等问题；在生产过程管理方面存在未按备案资料载明的技术要求生产产品等问题。','1.国家药监局要求安徽省药监局对该企业涉嫌违法的行为依法立案调查，并评估相关产品安全风险，必要时依法采取紧急控制措施。有关查处结果及时报告国家药监局。\n2.该企业完成全面整改并经安徽省药监局检查确认前不得恢复生产。有关整改和复产情况及时报告国家药监局。','2026年1月8日','附件\n\n安徽特仑沙克生物科技研究有限公司\n飞行检查结果\n\n企业名称	安徽特仑沙克生物科技研究有限公司	\n化妆品生产许可证编号	皖妆20220006	社会信用代码（组织机构代码）	91340102MA2RRWYE0Y	\n企业地址	合肥市新站区新蚌埠路3768号佳海工业城G90	\n检查单位	国家药监局食品药品审核查验中心	\n检查依据	《化妆品监督管理条例》《化妆品生产质量管理规范》\n《化妆品生产质量管理规范检查要点及判定原则》等	\n检查发现缺陷和问题	\n该企业在质量保证与控制方面存在未有效执行留样管理制度、未按规定保存留样记录等问题；在厂房设施与设备管理方面存在擅自改变生产车间的功能区域划分等问题；在物料与产品管理方面存在未有效执行物料进货查验记录制度等问题；在生产过程管理方面存在未按备案资料载明的技术要求生产产品等问题。	\n处理措施	\n1.国家药监局要求安徽省药监局对该企业涉嫌违法的行为依法立案调查，并评估相关产品安全风险，必要时依法采取紧急控制措施。有关查处结果及时报告国家药监局。\n2.该企业完成全面整改并经安徽省药监局检查确认前不得恢复生产。有关整改和复产情况及时报告国家药监局。	\n发布日期	2026年1月8日','2026-04-09 08:33:47','2026-04-09 08:33:47','1767946971033028279.doc','/uploads/supervisions/1775723627255-295641200.doc'),(18,'蔻丝芙国际贸易（深圳）有限公司',NULL,NULL,'深圳市宝安区西乡街道盐田社区银田工业区B2栋G317',NULL,NULL,NULL,NULL,'2025-08-19','2026-04-09 16:41:52','2026-04-09 16:41:52',23,1,'蔻丝芙国际贸易（深圳）有限公司飞行检查结果','/','91440300087709193M','国家药监局食品药品审核查验中心','《化妆品监督管理条例》《化妆品生产质量管理规范》\n《化妆品生产质量管理规范检查要点及判定原则》等','该企业在机构与人员方面存在质量安全负责人未有效履职等问题；在质量保证与控制方面存在未按要求执行质量管理体系自查制度、留样管理制度等问题；在生产过程管理方面存在未按要求执行产品放行管理制度等问题；在委托生产管理方面存在未按要求对受托生产企业生产活动进行监督等问题；在产品销售管理方面存在未按规定执行产品销售记录制度等问题。','1.国家药监局要求广东省药品监督管理局对该企业涉嫌违法的行为依法立案调查，并评估相关产品安全风险，必要时依法采取紧急控制措施。有关查处结果及时报告国家药监局。\n2.对检查中发现的不符合规定项目和问题，广东省药品监督管理局已责令该企业进行整改。该企业完成全面整改并经广东省药品监督管理局检查确认前不得恢复经营。有关整改情况及时报告国家药监局。','2025年8月19日','附件3\n\n蔻丝芙国际贸易（深圳）有限公司\n飞行检查结果\n\n企业名称	蔻丝芙国际贸易（深圳）有限公司	\n化妆品生产许可证编号	/	社会信用代码（组织机构代码）	91440300087709193M	\n企业地址	深圳市宝安区西乡街道盐田社区银田工业区B2栋G317	\n检查单位	国家药监局食品药品审核查验中心	\n检查依据	《化妆品监督管理条例》《化妆品生产质量管理规范》\n《化妆品生产质量管理规范检查要点及判定原则》等	\n检查发现缺陷和问题	\n该企业在机构与人员方面存在质量安全负责人未有效履职等问题；在质量保证与控制方面存在未按要求执行质量管理体系自查制度、留样管理制度等问题；在生产过程管理方面存在未按要求执行产品放行管理制度等问题；在委托生产管理方面存在未按要求对受托生产企业生产活动进行监督等问题；在产品销售管理方面存在未按规定执行产品销售记录制度等问题。	\n处理措施	\n1.国家药监局要求广东省药品监督管理局对该企业涉嫌违法的行为依法立案调查，并评估相关产品安全风险，必要时依法采取紧急控制措施。有关查处结果及时报告国家药监局。\n2.对检查中发现的不符合规定项目和问题，广东省药品监督管理局已责令该企业进行整改。该企业完成全面整改并经广东省药品监督管理局检查确认前不得恢复经营。有关整改情况及时报告国家药监局。	\n发布日期	2025年8月19日','2026-04-09 08:41:52','2026-04-09 08:41:52','1755678616812084964.docx','/uploads/supervisions/1775724112023-943543666.docx'),(19,'和世生物科技（重庆）有限公司',NULL,NULL,'重庆市丰都县兴义镇水天坪大道106号第15幢1-1',NULL,NULL,NULL,NULL,'2025-08-19','2026-04-09 16:41:52','2026-04-09 16:41:52',23,2,'和世生物科技（重庆）有限公司飞行检查结果','渝妆20240002','91500230MAC8GT272G','国家药监局食品药品审核查验中心','《化妆品监督管理条例》《化妆品生产质量管理规范》\n《化妆品生产质量管理规范检查要点及判定原则》等','该企业在机构与人员方面存在质量管理部门负责人未有效履职等问题；在生产过程管理方面存在未按照备案资料载明的技术要求生产产品等问题。','1.国家药监局要求重庆市药品监督管理局对该企业涉嫌违法的行为依法立案调查，并评估相关产品安全风险，必要时依法采取紧急控制措施。有关查处结果及时报告国家药监局。\n2.对检查中发现的不符合规定项目和问题，重庆市药品监督管理局已责令该企业进行整改。该企业完成全面整改并经重庆市药品监督管理局检查确认前不得恢复生产。有关整改和复产情况及时报告国家药监局。','2025年8月19日','附件2\n\n和世生物科技（重庆）有限公司\n飞行检查结果\n\n企业名称	和世生物科技（重庆）有限公司	\n化妆品生产许可证编号	渝妆20240002	社会信用代码（组织机构代码）	91500230MAC8GT272G	\n企业地址	重庆市丰都县兴义镇水天坪大道106号第15幢1-1	\n检查单位	国家药监局食品药品审核查验中心	\n检查依据	《化妆品监督管理条例》《化妆品生产质量管理规范》\n《化妆品生产质量管理规范检查要点及判定原则》等	\n检查发现缺陷和问题	\n该企业在机构与人员方面存在质量管理部门负责人未有效履职等问题；在生产过程管理方面存在未按照备案资料载明的技术要求生产产品等问题。	\n处理措施	\n1.国家药监局要求重庆市药品监督管理局对该企业涉嫌违法的行为依法立案调查，并评估相关产品安全风险，必要时依法采取紧急控制措施。有关查处结果及时报告国家药监局。\n2.对检查中发现的不符合规定项目和问题，重庆市药品监督管理局已责令该企业进行整改。该企业完成全面整改并经重庆市药品监督管理局检查确认前不得恢复生产。有关整改和复产情况及时报告国家药监局。	\n发布日期	2025年8月19日','2026-04-09 08:41:52','2026-04-09 08:41:52','1755678609005038501.docx','/uploads/supervisions/1775724112023-123006302.docx'),(20,'哈尔滨蜜雪儿化妆品有限公司',NULL,NULL,'黑龙江省哈尔滨市平房工业园区平房路123号',NULL,NULL,NULL,NULL,'2025-08-19','2026-04-09 16:41:52','2026-04-09 16:41:52',23,3,'哈尔滨蜜雪儿化妆品有限公司飞行检查结果','黑妆20160019','912301006071673333','国家药监局食品药品审核查验中心','《化妆品监督管理条例》《化妆品生产质量管理规范》\n《化妆品生产质量管理规范检查要点及判定原则》等','该企业在质量保证与控制方面存在未有效执行记录管理制度、检验管理制度等问题；在厂房设施与设备管理方面存在不同洁净级别的区域未保持相应压差、未有效执行生产设备管理制度等问题；在物料与产品管理方面存在未有效执行物料供应商遴选制度、未按规定贮存物料、未按要求对工艺用水水质定期监测等问题；在生产过程管理方面存在未按规定执行产品放行管理制度等问题。','1.国家药监局要求黑龙江省药品监督管理局对该企业涉嫌违法的行为依法立案调查，并评估相关产品安全风险，必要时依法采取紧急控制措施。有关查处结果及时报告国家药监局。\n2.对检查中发现的不符合规定项目和问题，黑龙江省药品监督管理局已责令该企业进行整改。该企业完成全面整改并经黑龙江省药品监督管理局检查确认前不得恢复生产。有关整改和复产情况及时报告国家药监局。','2025年8月19日','附件1\n\n哈尔滨蜜雪儿化妆品有限公司\n飞行检查结果\n\n企业名称	哈尔滨蜜雪儿化妆品有限公司	\n化妆品生产许可证编号	黑妆20160019	社会信用代码（组织机构代码）	912301006071673333	\n企业地址	黑龙江省哈尔滨市平房工业园区平房路123号	\n检查单位	国家药监局食品药品审核查验中心	\n检查依据	《化妆品监督管理条例》《化妆品生产质量管理规范》\n《化妆品生产质量管理规范检查要点及判定原则》等	\n检查发现缺陷和问题	\n该企业在质量保证与控制方面存在未有效执行记录管理制度、检验管理制度等问题；在厂房设施与设备管理方面存在不同洁净级别的区域未保持相应压差、未有效执行生产设备管理制度等问题；在物料与产品管理方面存在未有效执行物料供应商遴选制度、未按规定贮存物料、未按要求对工艺用水水质定期监测等问题；在生产过程管理方面存在未按规定执行产品放行管理制度等问题。	\n处理措施	\n1.国家药监局要求黑龙江省药品监督管理局对该企业涉嫌违法的行为依法立案调查，并评估相关产品安全风险，必要时依法采取紧急控制措施。有关查处结果及时报告国家药监局。\n2.对检查中发现的不符合规定项目和问题，黑龙江省药品监督管理局已责令该企业进行整改。该企业完成全面整改并经黑龙江省药品监督管理局检查确认前不得恢复生产。有关整改和复产情况及时报告国家药监局。	\n发布日期	2025年8月19日','2026-04-09 08:41:52','2026-04-09 08:41:52','1755678601848090190.docx','/uploads/supervisions/1775724112024-144345974.docx');
